 released:"5 November 1982 (UK)", label:"Dark Horse", producer:"George Harrison, Ray Cooper & Phil McDonald",
 recorded:"May – August 1982 · FPSHOT, Henley",
 tag:"A shrug from the tropics before a five-year break",
 charts:{UK:"—",US:"108",NO:"31"}, single:"“Wake Up My Love” – US No. 53",
 ratings:"AllMusic 2/5 · Rolling Stone (2004) 3/5 · Uncut 3/5",
